(5396292, 774396, 67258, '<td valign="top">A decent photo of the bike, but the backdrop is uninspiring to the point that it detracts severely.</td>', 'A decent photo of the bike, but the backdrop is uninspiring to the point that it detracts severely.', '2009-03-23 08:42:29.000000', NULL, 1),
(5396294, 775712, 67258, '<td valign="top">A good title.  Baeutiful colours, and pleasingly graduated.</td>', 'A good title.  Baeutiful colours, and pleasingly graduated.', '2009-03-23 08:43:56.000000', NULL, 1),
(5396307, 775708, 67258, '<td valign="top">The water is a bit too blue for my tastes, and theer is the hint of over-sharpening, but an otherwise pleasant scene with a well-balanced exposure.</td>', 'The water is a bit too blue for my tastes, and theer is the hint of over-sharpening, but an otherwise pleasant scene with a well-balanced exposure.', '2009-03-23 08:55:19.000000', NULL, 1),
(5396309, 775120, 67258, '<td valign="top">A sense of mania comes across well - somewhat disturbing, but in a good question-raising way.</td>', 'A sense of mania comes across well - somewhat disturbing, but in a good question-raising way.', '2009-03-23 08:56:17.000000', NULL, 1),
(5396311, 775521, 67258, '<td valign="top">I am not keen on your choice of processing technique, with the ''painted'' effect.  Much detail in the white of the cascading waterfall has been lost - but I do know how hard it is to balance the exposure, to retain detail in the shadow without blowing the highlights.  A pleasing composition, but a photo that as a whole doesn''t work for this viewer.</td>', 'I am not keen on your choice of processing technique, with the ''painted'' effect.  Much detail in the white of the cascading waterfall has been lost - but I do know how hard it is to balance the exposure, to retain detail in the shadow without blowing the highlights.  A pleasing composition, but a photo that as a whole doesn''t work for this viewer.', '2009-03-23 09:01:33.000000', NULL, 1),
(5396313, 775511, 67258, '<td valign="top">A very well balanced exposure, and a pleasing composition of what I imagine was quite a hard scene to compose from.</td>', 'A very well balanced exposure, and a pleasing composition of what I imagine was quite a hard scene to compose from.', '2009-03-23 09:02:35.000000', NULL, 1),
(5396316, 775259, 67258, '<td valign="top">I like this photo, with its quiet intimacy and observation, but might like it even more if the right side was cropped to the edge of the red.</td>', 'I like this photo, with its quiet intimacy and observation, but might like it even more if the right side was cropped to the edge of the red.', '2009-03-23 09:03:51.000000', NULL, 1),
(5396322, 775687, 15711, '<td valign="top">Oh that''s terrific but not sure of the selective de-sat.</td>', 'Oh that''s terrific but not sure of the selective de-sat.', '2009-03-23 09:06:12.000000', NULL, 1),
