(5396613, 775696, 18197, '<td valign="top">Okay smoke is cliche now, but the 1 second rule gave you room to explore further. I like the result.</td>', 'Okay smoke is cliche now, but the 1 second rule gave you room to explore further. I like the result.', '2009-03-23 12:41:42.000000', NULL, 1),
(5396615, 775294, 18197, '<td valign="top">The film noir feeling is perfect. I can see this as a backdrop for a gritty detective movie, or a subtle horror piece. Super well done.</td>', 'The film noir feeling is perfect. I can see this as a backdrop for a gritty detective movie, or a subtle horror piece. Super well done.', '2009-03-23 12:42:47.000000', NULL, 1),
