(5396624, 775692, 18197, '<td valign="top">For me the strength of the photo, besides the lovely result, is the mixture of focused and blurred components. From a distance, where the focused parts blur a bit, the composition is very good, too. Best of class.</td>', 'For me the strength of the photo, besides the lovely result, is the mixture of focused and blurred components. From a distance, where the focused parts blur a bit, the composition is very good, too. Best of class.', '2009-03-23 12:46:46.000000', NULL, 1),
(5396626, 775015, 18197, '<td valign="top">Strong focused black pilings(?) plus blurred water equals a superb photo, strengthened by the strong composition.</td>', 'Strong focused black pilings(?) plus blurred water equals a superb photo, strengthened by the strong composition.', '2009-03-23 12:47:53.000000', NULL, 1),
(5396628, 774510, 18197, '<td valign="top">Very nice lines here. Well done.</td>', 'Very nice lines here. Well done.', '2009-03-23 12:48:10.000000', NULL, 1),
