INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5400766, 775367, 60047, '<td valign="top">What a cool and dreamy shot. I wish I knew what I was seeing - then it would probably explain how this fits into the 1 second exposure idea. Great colors.</td>', 'What a cool and dreamy shot. I wish I knew what I was seeing - then it would probably explain how this fits into the 1 second exposure idea. Great colors.', '2009-03-25 18:21:50.000000', NULL, 1),
(5400771, 774992, 60047, '<td valign="top">The heavy pink on the tree looks like a post processing effect. Not sure if you intended to the horizon to be tilted. The subject of the photo isn''t doing a lot to illustrate the 1 second concept.</td>', 'The heavy pink on the tree looks like a post processing effect. Not sure if you intended to the horizon to be tilted. The subject of the photo isn''t doing a lot to illustrate the 1 second concept.', '2009-03-25 18:24:22.000000', NULL, 1),
(5400779, 775599, 60047, '<td valign="top">Given the warm tones and the large DOF, I am guessing this was done with a small aperture at the beginning or end of the day. That would explain the 1 second exposure. But the subject alone isn''t helping illustrate this in a strong manner. That being said, this is a beautiful location.</td>', 'Given the warm tones and the large DOF, I am guessing this was done with a small aperture at the beginning or end of the day. That would explain the 1 second exposure. But the subject alone isn''t helping illustrate this in a strong manner. That being said, this is a beautiful location.', '2009-03-25 18:29:11.000000', NULL, 1),
