(5401257, 775683, 81362, '<td valign="top">Nice catch of the jump from one static position to the next. Those who never saw one of these in operation might be expecting a blur.</td>', 'Nice catch of the jump from one static position to the next. Those who never saw one of these in operation might be expecting a blur.', '2009-03-25 22:41:44.000000', NULL, 1),
(5401263, 775648, 30364, '<td valign="top">That''s moving!  Even a bit of Doppler red shift appearing.  So I think it''s relatively good (sorry ... awful pun).  7.</td>', 'That''s moving!  Even a bit of Doppler red shift appearing.  So I think it''s relatively good (sorry ... awful pun).  7.', '2009-03-25 22:42:59.000000', NULL, 1),
