(5401422, 775516, 42495, '<td valign="top">Back for bump and comment.  Beautiful, soft, and delicate.  Excellent job on getting the texture to come out like that on the petals.</td>', 'Back for bump and comment.  Beautiful, soft, and delicate.  Excellent job on getting the texture to come out like that on the petals.', '2009-03-25 23:54:39.000000', NULL, 1),
