(5401431, 775103, 30364, '<td valign="top">The bus is good, for sure, but what I most like is the juxtaposition of the All Souls spire with the construction cranes.  Something reassuring about how these two make way for each other, across the centuries.  7.</td>', 'The bus is good, for sure, but what I most like is the juxtaposition of the All Souls spire with the construction cranes.  Something reassuring about how these two make way for each other, across the centuries.  7.', '2009-03-26 00:01:28.000000', NULL, 1),
(5401439, 774728, 42495, '<td valign="top">Very nice; love the tones.</td>', 'Very nice; love the tones.', '2009-03-26 00:08:05.000000', NULL, 1),
(5401443, 774510, 42495, '<td valign="top">Back for comment and bump.  Lines lead me across the photo and great sense of motion.  This reminds me of something Ursula would do.</td>', 'Back for comment and bump.  Lines lead me across the photo and great sense of motion.  This reminds me of something Ursula would do.', '2009-03-26 00:09:34.000000', NULL, 1),
(5401450, 775250, 42495, '<td valign="top">Back for bump and comment.  Very nice; I can only image how many tries it took to get this.  Love the emotional content.</td>', 'Back for bump and comment.  Very nice; I can only image how many tries it took to get this.  Love the emotional content.', '2009-03-26 00:11:52.000000', NULL, 1),
