(5404776, 775532, 31637, '<td valign="top">Heavenly!<br/> <br/>Bumping to 10, good luck, the colors here add alot to it for me, the greenish gray water and golden rocks.</td>', 'Heavenly! Bumping to 10, good luck, the colors here add alot to it for me, the greenish gray water and golden rocks.', '2009-03-28 04:32:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5404777, 775248, 31637, '<td valign="top">Awesome tonal range and exposure, thats an excellent night shot, maybe a bit too blue.</td>', 'Awesome tonal range and exposure, thats an excellent night shot, maybe a bit too blue.', '2009-03-28 04:32:56.000000', NULL, 1),
(5404817, 775250, 23002, '<td valign="top">ok, I like the concept, but because you used two separate flashes, instead of some hot light and one rear curtain sync flash, you end up with a two headded monster instead of a boy shaking his head...sorry, it just freaks me out.</td>', 'ok, I like the concept, but because you used two separate flashes, instead of some hot light and one rear curtain sync flash, you end up with a two headded monster instead of a boy shaking his head...sorry, it just freaks me out.', '2009-03-28 06:43:05.000000', NULL, 1),
(5404818, 775583, 23002, '<td valign="top">this is great!  Druli?</td>', 'this is great!  Druli?', '2009-03-28 06:47:13.000000', NULL, 1),
(5404819, 775713, 23002, '<td valign="top">I think it would do great in a different challenge.  The idea of this one is to portray time or motion with a 1 second exposure.  Although I am sure this is a 1 second exposure, it does not  meet the spirit of the challenge.</td>', 'I think it would do great in a different challenge.  The idea of this one is to portray time or motion with a 1 second exposure.  Although I am sure this is a 1 second exposure, it does not  meet the spirit of the challenge.', '2009-03-28 06:50:32.000000', NULL, 1),
(5404849, 774585, 104624, '<td valign="top">I prefered this one to all the other clocks...But the idéa seems used up.</td>', 'I prefered this one to all the other clocks...But the idéa seems used up.', '2009-03-28 08:13:29.000000', NULL, 1),
(5404977, 775278, 38478, '<td valign="top">I find the foreground to be a bit cluttered, cropping wouldn''t help because you''d lose the comp. The only thing I can see is moving the camera a few feet closer to the edge? or zoom in if that''s an option. Great shot otherwise - 8</td>', 'I find the foreground to be a bit cluttered, cropping wouldn''t help because you''d lose the comp. The only thing I can see is moving the camera a few feet closer to the edge? or zoom in if that''s an option. Great shot otherwise - 8', '2009-03-28 09:15:13.000000', NULL, 1),
(5404978, 775434, 100318, '<td valign="top">Great color contrast, perfect balance within the picture. Just love it.</td>', 'Great color contrast, perfect balance within the picture. Just love it.', '2009-03-28 09:15:29.000000', NULL, 1),
(5404980, 775702, 100318, '<td valign="top">Wonderful picture. Simple, sexual and I can feel the water when I look at the picture.</td>', 'Wonderful picture. Simple, sexual and I can feel the water when I look at the picture.', '2009-03-28 09:16:48.000000', NULL, 1),
(5404981, 775675, 38478, '<td valign="top">Beautiful; I like the contrast between the serene flowing water above the fall and the crashing water down the fall, I just wish there was a bit more of that, it gets lost in the darkness. 8</td>', 'Beautiful; I like the contrast between the serene flowing water above the fall and the crashing water down the fall, I just wish there was a bit more of that, it gets lost in the darkness. 8', '2009-03-28 09:17:04.000000', NULL, 1),
(5404982, 775516, 38478, '<td valign="top">Very well done closeup. I find my eye distracted by the spot of green on the upper right edge, I would have burned that a bit to hide it. 8</td>', 'Very well done closeup. I find my eye distracted by the spot of green on the upper right edge, I would have burned that a bit to hide it. 8', '2009-03-28 09:18:44.000000', NULL, 1),
(5404986, 775082, 38478, '<td valign="top">Quite dark, and that works well here. 8</td>', 'Quite dark, and that works well here. 8', '2009-03-28 09:19:45.000000', NULL, 1),
(5404993, 775072, 38478, '<td valign="top">At 1 second, every aspect of this lemon (?) should have been razor sharp. Maybe you''re going for a sun rising in a blue sky motif? or a slow laid back lemonade type of day? Since I''m guessing, you can tell that I didn''t get it.</td>', 'At 1 second, every aspect of this lemon (?) should have been razor sharp. Maybe you''re going for a sun rising in a blue sky motif? or a slow laid back lemonade type of day? Since I''m guessing, you can tell that I didn''t get it.', '2009-03-28 09:23:19.000000', NULL, 1),
(5404996, 775683, 38478, '<td valign="top">I don''t mind the grain, but there''s way too much contrast. With a bit more light, you could have stopped down more and gotten the entire watch face in focus.</td>', 'I don''t mind the grain, but there''s way too much contrast. With a bit more light, you could have stopped down more and gotten the entire watch face in focus.', '2009-03-28 09:25:00.000000', NULL, 1),
(5404997, 775209, 38478, '<td valign="top">By itself this doesn''t work for me...perhaps as part of a series?</td>', 'By itself this doesn''t work for me...perhaps as part of a series?', '2009-03-28 09:27:32.000000', NULL, 1),
(5404999, 775424, 38478, '<td valign="top">This has the right idea, but imho the motion should be smooth, not so jittery. Also, the white flower is blown out. This is a nice subject for a photo, but not for this challenge.</td>', 'This has the right idea, but imho the motion should be smooth, not so jittery. Also, the white flower is blown out. This is a nice subject for a photo, but not for this challenge.', '2009-03-28 09:29:31.000000', NULL, 1),
(5405001, 774510, 38478, '<td valign="top">so I''ve been trying to find something to comment on as to why I''m only giving this a 9 r/t a 10. The composition is perfect; meets the challenge perfectly; maybe the white patch in the far upper right corner?<br/>later -- forget all that, I''m just changing it to a 10.</td>', 'so I''ve been trying to find something to comment on as to why I''m only giving this a 9 r/t a 10. The composition is perfect; meets the challenge perfectly; maybe the white patch in the far upper right corner?later -- forget all that, I''m just changing it to a 10.', '2009-03-28 09:30:39.000000', NULL, 1),
(5405004, 775705, 38478, '<td valign="top">Wonderful feeling on this; I would have composed it a bit differently and not cut off the upper branch (or removed it entirely), but maybe that''s why I''m getting 5.7s and you''re getting 9s!</td>', 'Wonderful feeling on this; I would have composed it a bit differently and not cut off the upper branch (or removed it entirely), but maybe that''s why I''m getting 5.7s and you''re getting 9s!', '2009-03-28 09:31:56.000000', NULL, 1),
(5405023, 775007, 38478, '<td valign="top">This is a great location with a wonderful reflection. Its just too soft, dark and brown. <br/> <br/>Use levels to turn the snow white, saturate the blue sky just a bit and sharpen overall. Just a guess, but is this a crop of a much larger shot? <br/> <br/>It could also be better if you used the full 720 pixels allowed under advanced editing.</td>', 'This is a great location with a wonderful reflection. Its just too soft, dark and brown.  Use levels to turn the snow white, saturate the blue sky just a bit and sharpen overall. Just a guess, but is this a crop of a much larger shot?  It could also be better if you used the full 720 pixels allowed under advanced editing.', '2009-03-28 09:47:27.000000', NULL, 1),
